#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>

void sync_directories(const char *src, const char *dst) {
  DIR *dir;
  struct dirent *entry;
  char src_path[256], dst_path[256];

  dir = opendir(src);
  if (dir == NULL) {
    perror("opendir");
    return;
  }

  while ((entry = readdir(dir)) != NULL) {
    if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
      snprintf(src_path, sizeof(src_path), "%s/%s", src, entry->d_name);
      snprintf(dst_path, sizeof(dst_path), "%s/%s", dst, entry->d_name);

      struct stat statbuf;
      if (stat(src_path, &statbuf) == 0) {
        if (S_ISREG(statbuf.st_mode)) {
          FILE *src_file = fopen(src_path, "rb");
          FILE *dst_file = fopen(dst_path, "wb");

          if (src_file && dst_file) {
            char buffer[1024];
            size_t n;
            while ((n = fread(buffer, 1, sizeof(buffer), src_file)) > 0) {
              fwrite(buffer, 1, n, dst_file);
            }
            fclose(src_file);
            fclose(dst_file);
          }
        } else if (S_ISDIR(statbuf.st_mode)) {
          mkdir(dst_path, 0755);
          sync_directories(src_path, dst_path);
        }
      }
    }
  }

  closedir(dir);
}

int main(int argc, char *argv[]) {
  if (argc != 3) {
    fprintf(stderr, "Usage: %s <source_dir> <destination_dir>\n", argv[0]);
    return 1;
  }

  sync_directories(argv[1], argv[2]);
  return 0;
}

