int main() {
  const char *filename = "example.txt";
  const char *text = "Memory-mapped file example.";

  // Write to file
  std::ofstream outFile(filename);
  outFile << text;
  outFile.close();

  // Memory map the file
  int fd = open(filename, O_RDONLY);
  if (fd == -1) {
    perror("open");
    return 1;
  }

  off_t length = lseek(fd, 0, SEEK_END);
  lseek(fd, 0, SEEK_SET);

  char *data = (char *)mmap(nullptr, length, PROT_READ, MAP_PRIVATE, fd, 0);
  if (data == MAP_FAILED) {
    perror("mmap");
    close(fd);
    return 1;
  }

  std::cout << "Mapped file contents: " << std::string(data, length) << std::endl;

  munmap(data, length);
  close(fd);
  return 0;
}

