using namespace CryptoPP;

int main() {
  AutoSeededRandomPool rng;

  // Generate RSA keys
  RSA::PrivateKey privateKey;
  RSA::PublicKey publicKey;

  privateKey.GenerateRandomWithKeySize(rng, 2048);
  publicKey.AssignFrom(privateKey);

  std::string message = "Hello, world!";
  std::string signature;

  // Sign the message
  try {
    RSASSA_PKCS1v15_SHA_Signer signer(privateKey);
    StringSource ss(message, true, new SignerFilter(rng, signer, new StringSink(signature)));
  } catch (const Exception& e) {
    std::cerr << e.what() << std::endl;
  }

  std::string encoded_signature;
  StringSource(signature, true, new HexEncoder(new StringSink(encoded_signature)));

  std::cout << "Signature: " << encoded_signature << std::endl;

  // Verify the signature
  bool valid = false;
  try {
    RSASSA_PKCS1v15_SHA_Verifier verifier(publicKey);
    StringSource ss(signature + message, true, new HexDecoder(new SignatureVerificationFilter(verifier, &valid)));
  } catch (const Exception& e) {
    std::cerr << e.what() << std::endl;
  }

  std::cout << "Signature is " << (valid ? "valid" : "invalid") << std::endl;

  return 0;
}

