double evaluate_polynomial(double a, double b, double c, double d, double x) {
  return a * pow(x, 3) + b * pow(x, 2) + c * x + d;
}

double evaluate_derivative(double a, double b, double c, double x) {
  return 3 * a * pow(x, 2) + 2 * b * x + c;
}

double find_root(double a, double b, double c, double d, double initial_guess) {
  double x = initial_guess;
  double tolerance = 1e-7;
  for (int i = 0; i < 100; i++) {
    double fx = evaluate_polynomial(a, b, c, d, x);
    double fpx = evaluate_derivative(a, b, c, x);
    if (fabs(fpx) < tolerance) {
      printf("Derivative too small; no convergence.\n");
      return x;
    }
    x = x - fx / fpx;
    if (fabs(fx) < tolerance) {
      break;
    }
  }
  return x;
}

