class ExpressionManager : public QWidget {
  Q_OBJECT

public:
  ExpressionManager(QWidget *parent = nullptr) : QWidget(parent) {
    QVBoxLayout *layout = new QVBoxLayout(this);

    expressionInput = new QLineEdit(this);
    expressionInput->setPlaceholderText("Enter the expression");
    layout->addWidget(expressionInput);

    chercherInput = new QLineEdit(this);
    chercherInput->setPlaceholderText("Search");
    layout->addWidget(chercherInput);

    remplacerInput = new QLineEdit(this);
    remplacerInput->setPlaceholderText("Replace with");
    layout->addWidget(remplacerInput);

    QPushButton *replaceButton = new QPushButton("Replace", this);
    layout->addWidget(replaceButton);

    resultOutput = new QTextEdit(this);
    resultOutput->setReadOnly(true);
    layout->addWidget(resultOutput);

    connect(replaceButton, &QPushButton::clicked, this, &ExpressionManager::replaceText);
  }

private slots:
  void replaceText() {
    QString expression = expressionInput->text();
    QString chercher = chercherInput->text();
    QString remplacer = remplacerInput->text();

    QString modified = expression.replace(chercher, remplacer);
    resultOutput->setText(modified);
  }

private:
  QLineEdit *expressionInput;
  QLineEdit *chercherInput;
  QLineEdit *remplacerInput;
  QTextEdit *resultOutput;
};

int main(int argc, char *argv[]) {
  QApplication app(argc, argv);
  ExpressionManager window;
  window.setWindowTitle("Search and Replace");
  window.resize(400, 300);
  window.show();
  return app.exec();
}

