void calculateStatistics(const std::vector<double>& savings, double& total, double& average, double& max, double& min, double& median, double& stddev) {
  total = std::accumulate(savings.begin(), savings.end(), 0.0);
  max = *std::max_element(savings.begin(), savings.end());
  min = *std::min_element(savings.begin(), savings.end());

  average = total / savings.size();

  // Median calculation
  std::vector<double> sortedSavings = savings; 
  std::sort(sortedSavings.begin(), sortedSavings.end());
  median = (sortedSavings.size() % 2 == 0) ? 
    (sortedSavings[sortedSavings.size()/2 - 1] + sortedSavings[sortedSavings.size()/2]) / 2 : 
    sortedSavings[sortedSavings.size()/2];

  // Standard deviation calculation
  double sumSquares = 0;
  for (double amount : savings) {
    sumSquares += (amount - average) * (amount - average);
  }
  stddev = std::sqrt(sumSquares / savings.size());
}

