void aes_encrypt(const unsigned char *plaintext, const unsigned char *key, unsigned char *ciphertext) {
  __m128i key_schedule[11];
  key_schedule[0] = _mm_loadu_si128((__m128i*)key);
  for (int i = 1; i < 11; i++) {
    key_schedule[i] = _mm_aeskeygenassist_si128(key_schedule[i - 1], i);
  }
  __m128i block = _mm_loadu_si128((__m128i*)plaintext);
  block = _mm_xor_si128(block, key_schedule[0]);
  for (int i = 1; i < 10; i++) {
    block = _mm_aesenc_si128(block, key_schedule[i]);
  }
  block = _mm_aesenclast_si128(block, key_schedule[10]);
  _mm_storeu_si128((__m128i*)ciphertext, block);
}

