namespace plt = matplotlibcpp;

double linearRegression(const std::vector<double>& x, const std::vector<double>& y, double& slope, double& intercept) {
  double n = x.size();
  double sum_x = 0, sum_y = 0, sum_xy = 0, sum_xx = 0;

  for (size_t i = 0; i < n; i++) {
    sum_x += x[i];
    sum_y += y[i];
    sum_xy += x[i] * y[i];
    sum_xx += x[i] * x[i];
  }

  slope = (n * sum_xy - sum_x * sum_y) / (n * sum_xx - sum_x * sum_x);
  intercept = (sum_y - slope * sum_x) / n;
  return slope * n;
}

int main() {
  // Sample data
  std::vector<std::string> days = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"};
  std::vector<double> sales = {150, 200, 250, 300, 350, 400, 450};
  std::vector<double> profits = {50, 80, 120, 160, 200, 250, 300};

  // Regression analysis
  double slope, intercept;
  linearRegression(sales, profits, slope, intercept);
  std::vector<double> regressionLine;
  for (double x : sales) {
    regressionLine.push_back(slope * x + intercept);
  }

  // Create a bar chart for sales
  plt::figure();
  plt::bar(days, sales);
  plt::title("Daily Sales Data");
  plt::xlabel("Day of the Week");
  plt::ylabel("Sales");
  plt::show();

  // Create a line chart for profits and regression line
  plt::figure();
  plt::plot(days, profits, "ro-", label="Profit");
  plt::plot(days, regressionLine, "b--", label="Regression Line");
  plt::title("Daily Profit Data with Regression Line");
  plt::xlabel("Day of the Week");
  plt::ylabel("Profit");
  plt::legend();
  plt::show();

  return 0;
}

