class Event {
public:
  std::string title;
  std::string date; // YYYY-MM-DD
  std::string description;
  bool isRecurring;
  std::string category; // New field
  std::set<Employee*> attendees; // New field

  Event(std::string t, std::string d, std::string desc, bool recurring = false, std::string cat = "") 
    : title(t), date(d), description(desc), isRecurring(recurring), category(cat) {}

  void display() {
    std::cout << "Event: " << title << ", Date: " << date 
         << ", Description: " << description 
         << ", Recurring: " << (isRecurring ? "Yes" : "No") 
         << ", Category: " << category << std::endl;
  }

  void addAttendee(Employee* emp) {
    attendees.insert(emp);
  }

  bool hasConflict(const Event& other) const {
    return date == other.date && !attendees.empty();
  }
};

class Employee {
public:
  std::string name;
  std::string position;
  double salary;
  double performanceRating;
  std::vector<Event> events;

  Employee(std::string n, std::string p, double s) 
    : name(n), position(p), salary(s), performanceRating(0) {}

  void display() {
    std::cout << position << ": " << name << ", Salary: " << salary 
         << ", Performance Rating: " << performanceRating << std::endl;
    std::cout << "Events:" << std::endl;
    for (const auto& event : events) {
      event.display();
    }
  }

  void addEvent(const Event& event) {
    for (const auto& e : events) {
      if (e.hasConflict(event)) {
        std::cout << "Conflict detected: " << e.title << std::endl;
        return;
      }
    }
    events.push_back(event);
    events.back().addAttendee(this); // Automatically add employee as attendee
  }

  void notifyUpcomingEvents(const std::string& currentDate) {
    for (const auto& event : events) {
      if (event.date == currentDate) {
        std::cout << "Notification: " << name << ", you have an upcoming event: " << event.title << std::endl;
      }
    }
  }
};

