  scanf("%d", &number);
  send(sock, &number, sizeof(number), 0);

  long result;
  char response[256];
  recv(sock, response, sizeof(response), 0);
  if (strstr(response, "Error")) {
    printf("%s\n", response);
  } else {
    memcpy(&result, response, sizeof(result));
    printf("Factorial of %d is %ld\n", number, result);
  }

  close(sock);
