class LimitedLoadQueue {
private:
  std::string filename;
  size_t load_limit;

public:
  LimitedLoadQueue(const std::string& fname, size_t limit) : filename(fname), load_limit(limit) {
    std::ofstream file(filename); // Create the file if it doesn't exist
  }

  void enqueue(const std::string& item) {
    std::ofstream file(filename, std::ios::app);
    file << item << std::endl;
  }

  std::queue<std::string> dequeue_all() {
    std::ifstream file(filename);
    std::queue<std::string> items;
    std::string line;

    while (std::getline(file, line) && items.size() < load_limit) {
      items.push(line);
    }

    // Rewrite file without dequeued items
    std::ofstream outFile(filename);
    for (const auto& item : items) {
      outFile << item << std::endl;
    }

    return items;
  }
};

