class CarInventory {
public:
  std::vector<Car> cars;

  void addCar(const Car& car) {
    cars.push_back(car);
  }

  void displayCars() {
    for (const auto& car : cars) {
      car.displayInfo();
    }
  }

  void bulkAddCars(const std::vector<Car>& newCars) {
    cars.insert(cars.end(), newCars.begin(), newCars.end());
  }

  void sortCarsByYear() {
    std::sort(cars.begin(), cars.end(), [](const Car& a, const Car& b) {
      return a.year < b.year;
    });
  }
};

