#define SIZE 20

void printGrid(int grid[SIZE][SIZE]) {
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      printf("%c ", grid[i][j] ? 'O' : '.');
    }
    printf("\n");
  }
}

void updateGrid(int grid[SIZE][SIZE]) {
  int newGrid[SIZE][SIZE] = {0};
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      int total = 0;
      for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
          if (x == 0 && y == 0) continue;
          int ni = (i + x + SIZE) % SIZE;
          int nj = (j + y + SIZE) % SIZE;
          total += grid[ni][nj];
        }
      }
      if (grid[i][j]) {
        newGrid[i][j] = (total == 2 || total == 3);
      } else {
        newGrid[i][j] = (total == 3);
      }
    }
  }
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      grid[i][j] = newGrid[i][j];
    }
  }
}

int main() {
  int grid[SIZE][SIZE] = {0};
  srand(time(NULL));

  // Initialize grid randomly
  for (int i = 0; i < SIZE; i++) {
    for (int j = 0; j < SIZE; j++) {
      grid[i][j] = rand() % 2;
    }
  }

  int running = 1;
  while (1) {
    if (_kbhit()) {
      _getch(); // Pause/resume on key press
      running = !running;
    }
    if (running) {
      printGrid(grid);
      updateGrid(grid);
      usleep(200000); // Delay for 0.2 seconds
      printf("\033[H\033[J"); // Clear the console
    }
  }

  return 0;
}

