using namespace std;

unordered_map<string, unordered_map<string, variant<string, double, bool>>> inventory;
vector<tuple<string, string, unordered_map<string, variant<string, double, bool>>> logActions;

void addItem(const string& id, const string& description, double price, bool availability) {
  inventory[id] = {{"description", description}, {"price", price}, {"availability", availability}};
  logActions.emplace_back("add", id, inventory[id]);
}

void updateItem(const string& id, const string& description = "", double price = -1, bool availability = false) {
  if (inventory.find(id) == inventory.end()) {
    cout << "Item not found." << endl;
    return;
  }

  auto previousState = inventory[id];

  if (!description.empty()) {
    inventory[id]["description"] = description;
  }
  if (price != -1) {
    inventory[id]["price"] = price;
  }
  if (availability) {
    inventory[id]["availability"] = availability;
  }

  logActions.emplace_back("update", id, previousState);
}

void deleteItem(const string& id) {
  if (inventory.find(id) == inventory.end()) {
    cout << "Item not found." << endl;
    return;
  }

  auto previousState = inventory[id];
  inventory.erase(id);
  logActions.emplace_back("delete", id, previousState);
}

void undoAction() {
  if (logActions.empty()) {
    cout << "No actions to undo." << endl;
    return;
  }

  auto lastAction = logActions.back();
  logActions.pop_back();

  string actionType = get<0>(lastAction);
  string id = get<1>(lastAction);
  auto previousState = get<2>(lastAction);

  if (actionType == "add") {
    inventory.erase(id);
  } else if (actionType == "update") {
    inventory[id] = previousState;
  } else if (actionType == "delete") {
    inventory[id] = previousState;
  }
}

