double calculateMean(double scores[], int n) {
  double sum = 0;
  for (int i = 0; i < n; i++) {
    sum += scores[i];
  }
  return sum / n;
}

double calculateMedian(double scores[], int n) {
  qsort(scores, n, sizeof(double), compare);
  return n % 2 == 0 ? (scores[n / 2 - 1] + scores[n / 2]) / 2 : scores[n / 2];
}

int compare(const void *a, const void *b) {
  return (*(double *)a > *(double *)b) - (*(double *)a < *(double *)b);
}

double calculateStandardDeviation(double scores[], int n, double mean) {
  double sum = 0;
  for (int i = 0; i < n; i++) {
    sum += pow(scores[i] - mean, 2);
  }
  return sqrt(sum / n);
}

void categorizeScores(double scores[], int n) {
  int categories[5] = {0}; // A, B, C, D, F
  for (int i = 0; i < n; i++) {
    if (scores[i] >= 90) categories[0]++;
    else if (scores[i] >= 80) categories[1]++;
    else if (scores[i] >= 70) categories[2]++;
    else if (scores[i] >= 60) categories[3]++;
    else categories[4]++;
  }
  printf("Grade Categories:\n");
  printf("A: %d, B: %d, C: %d, D: %d, F: %d\n", categories[0], categories[1], categories[2], categories[3], categories[4]);
}

void printHistogram(double scores[], int n) {
  int bins[10] = {0};
  for (int i = 0; i < n; i++) {
    if (scores[i] >= 0 && scores[i] < 100) {
      bins[(int)(scores[i] / 10)]++;
    }
  }
  printf("Histogram:\n");
  for (int i = 0; i < 10; i++) {
    printf("%2d-%2d: ", i * 10, (i + 1) * 10);
    for (int j = 0; j < bins[i]; j++) {
      printf("*");
    }
    printf("\n");
  }
}

