                     SDL_WINDOWPOS_CENTERED,
                     WINDOW_WIDTH, WINDOW_HEIGHT,
                     0);
  if (!window) {
    fprintf(stderr, "Could not create window: %s\n", SDL_GetError());
    return 1;
  }

  SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, 0);
