}

void* handle_client(void* arg) {
  int client_fd = *(int*)arg;
  free(arg);

  int number;
  read(client_fd, &number, sizeof(number));

  if (number < 0) {
    const char* error_msg = "Error: Negative number";
    write(client_fd, error_msg, strlen(error_msg) + 1);
  } else {
    long result = factorial(number);
    write(client_fd, &result, sizeof(result));
  }

  close(client_fd);
  return nullptr;
}

