struct WeightedUnionFind{
  vector<int> par;
  vector<int> ws; /  WeightedUnionFind(int n) : par(n,-1), ws(n,0){}

  int find(int x){
    if(par[x] < 0){
      return x;
    }else{
      int parent = find(par[x]);
      ws[x] += ws[par[x]];
      return par[x] = parent;
    }
  }

  int weight(int x){
    find(x); 
    return ws[x];
  }

  bool unite(int x, int y, int w){ // x <-(w)- y (x + w = y)
    w += weight(x); 
    w -= weight(y);
    x = find(x); y = find(y);

    if(x != y){
      if(par[y] < par[x]) { 
