#include <stdio.h>
#include <stdlib.h>

#define MAX 100

typedef struct PriorityQueue {
  int size;
  int array[MAX];
} PriorityQueue;

void initQueue(PriorityQueue* pq) {
  pq->size = 0;
}

void swap(int* a, int* b) {
  int temp = *a;
  *a = *b;
  *b = temp;
}

void heapify(PriorityQueue* pq, int i) {
  int largest = i;
  int left = 2 * i + 1;
  int right = 2 * i + 2;

  if (left < pq->size && pq->array[left] > pq->array[largest])
    largest = left;

  if (right < pq->size && pq->array[right] > pq->array[largest])
    largest = right;

  if (largest != i) {
    swap(&pq->array[i], &pq->array[largest]);
    heapify(pq, largest);
  }
}

void insert(PriorityQueue* pq, int key) {
  if (pq->size == MAX) {
    printf("Priority Queue is full\n");
    return;
  }
  pq->array[pq->size] = key;
  pq->size++;
  for (int i = pq->size / 2 - 1; i >= 0; i--) {
    heapify(pq, i);
  }
}

int extractMax(PriorityQueue* pq) {
  if (pq->size == 0) {
    printf("Priority Queue is empty\n");
    return -1;
  }
  int root = pq->array[0];
  pq->array[0] = pq->array[pq->size - 1];
  pq->size--;
  heapify(pq, 0);
  return root;
}

