int main() {
  const int width = 800;
  const int height = 600;
  sf::RenderWindow window(sf::VideoMode(width, height), "Lissajous Curve");

  sf::VertexArray lissajous(sf::PrimitiveType::LinesStrip);
  double a = 200, b = 200; // Amplitude
  double delta = M_PI / 2; // Phase difference

  for (double t = 0; t < 2 * M_PI; t += 0.01) {
    double x = a * sin(3 * t + delta);
    double y = b * sin(2 * t);
    lissajous.append(sf::Vertex(sf::Vector2f(width / 2 + x, height / 2 + y), sf::Color::White));
  }

  while (window.isOpen()) {
    sf::Event event;
    while (window.pollEvent(event)) {
      if (event.type == sf::Event::Closed)
        window.close();
    }

    window.clear();
    window.draw(lissajous);
    window.display();
  }

  return 0;
}

