#include <stdio.h>

double convert_volume(double value, const char* from_unit, const char* to_unit) {
  // Conversion factors
  double factors[] = {1, 10, 100}; // L, dL, cL
  const char* units[] = {"L", "dL", "cL"};

  int from_index = 0, to_index = 0;
  for (int i = 0; i < 3; i++) {
    if (strcmp(from_unit, units[i]) == 0) from_index = i;
    if (strcmp(to_unit, units[i]) == 0) to_index = i;
  }

  return value * (factors[from_index] / factors[to_index]);
}

int main() {
  double volume = 5; // in liters
  double volume_dl = convert_volume(volume, "L", "dL");
  double volume_cl = convert_volume(volume, "L", "cL");
  printf("%.2f liters is equal to %.2f deciliters and %.2f centiliters.\n", volume, volume_dl, volume_cl);

  double volume_cl = 500;
  double volume_l = convert_volume(volume_cl, "cL", "L");
  printf("%.2f centiliters is equal to %.2f liters.\n", volume_cl, volume_l);

  return 0;
}

