  std::string make;
  std::string model;
  int year;
  std::string licensePlate;

  Car(std::string make, std::string model, int year, std::string licensePlate) 
    : make(make), model(model), year(year), licensePlate(licensePlate) {}

  void displayInfo() {
    std::cout << year << " " << make << " " << model 
         << " | License Plate: " << licensePlate << std::endl;
  }
};

class CarInventory {
public:
  std::vector<Car> cars;

  void addCar(const Car& car) {
    cars.push_back(car);
  }

  void displayCars() {
    for (const auto& car : cars) {
      car.displayInfo();
    }
  }

  Car* searchByLicensePlate(const std::string& licensePlate) {
    for (auto& car : cars) {
      if (car.licensePlate == licensePlate) {
        return &car;
      }
    }
    return nullptr;
  }

  void updateCar(const std::string& licensePlate, const std::string& newMake, 
          const std::string& newModel, int newYear) {
    Car* car = searchByLicensePlate(licensePlate);
    if (car) {
      car->make = newMake;
      car->model = newModel;
      car->year = newYear;
    }
  }

  void deleteCar(const std::string& licensePlate) {
    cars.erase(std::remove_if(cars.begin(), cars.end(),
      [&licensePlate](Car& car) { return car.licensePlate == licensePlate; }), cars.end());
  }
};

