}

std::vector<std::string> getHighestAverage(const std::map<std::string, std::vector<int>>& students) {
  double highestAverage = -1;
  std::vector<std::string> topStudents;

  for (const auto& [name, marks] : students) {
    double average = calculateAverage(marks);
    if (average > highestAverage) {
      highestAverage = average;
      topStudents = {name};
    } else if (average == highestAverage) {
      topStudents.push_back(name);
    }
  }

  return topStudents;
}

