std::string getForecast(const std::string& apiKey, const std::string& city) {
  CURL* curl;
  CURLcode res;
  std::string readBuffer;

  curl = curl_easy_init();
  if(curl) {
    std::string url = "http://api.openweathermap.org/data/2.5/forecast?q=" + city + "&appid=" + apiKey + "&units=metric";
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

    res = curl_easy_perform(curl);
    curl_easy_cleanup(curl);
  }

  return readBuffer;
}

void parseForecastData(const std::string& data) {
  auto j = json::parse(data);
  for (const auto& item : j["list"].items()) {
    if (item.key() < 5) { // Only first 5 forecasts
      std::string date = item.value()["dt_txt"];
      double temp = item.value()["main"]["temp"];
      std::string description = item.value()["weather"][0]["description"];
      std::cout << date << ": " << temp << "°C, " << description << std::endl;
    }
  }
}

