      if (std::find(lettersToRemember.begin(), lettersToRemember.end(), letter) != lettersToRemember.end()) {
        correctCount++;
      }
    }

    std::cout << "You remembered " << correctCount << " out of " << lettersToRemember.size() << " letters.\n";
