int countNeighbors(int grid[][DEFAULT_SIZE], int x, int y, int size) {
  int count = 0;
  for (int i = -1; i <= 1; i++) {
    for (int j = -1; j <= 1; j++) {
      if (i == 0 && j == 0) continue;
      int ni = (x + i + size) % size; // wrap-around
