}

// C: Dynamic Linking
#include <stdio.h>
#include <dlfcn.h>

int main() {
  void *handle;
  void (*func)();
  char *error;

  handle = dlopen("./libexample.so", RTLD_LAZY);
  if (!handle) {
    fprintf(stderr, "%s\n", dlerror());
    return 1;
  }

  dlerror(); // Clear any existing error

  func = dlsym(handle, "example_function");
  if ((error = dlerror()) != NULL) {
    fprintf(stderr, "%s\n", error);
    return 1;
  }

  func(); // Call the function

  dlclose(handle);
  return 0;
}

