#include <string>
#include <variant>
#include <fstream>
#include <sstream>
#include <ctime>

using namespace std;

unordered_map<string, unordered_map<string, variant<string, double, bool, int>>> inventory;

time_t getExpirationTime(const string& expiration) {
  struct tm tm {};
  strptime(expiration.c_str(), "%Y-%m-%d", &tm);
  return mktime(&tm);
}

void addItem(const string& id, const string& description, double price, bool availability, int quantity, const string& expiration) {
  inventory[id] = {
    {"description", description},
    {"price", price},
    {"availability", availability},
    {"quantity", quantity},
    {"expiration", expiration}
  };
}

void checkExpirations() {
  time_t now = time(0);
  for (const auto& [id, item] : inventory) {
    if (getExpirationTime(get<string>(item.at("expiration"))) < now + 3 * 24 * 60 * 60) {
      cout << "Alert: Item '" << get<string>(item.at("description")) << "' (ID: " << id << ") is expiring soon!" << endl;
    }
  }
}

void checkLowStock() {
  for (const auto& [id, item] : inventory) {
    if (get<int>(item.at("quantity")) < 10) {
      cout << "Alert: Item '" << get<string>(item.at("description")) << "' (ID: " << id << ") is low on stock!" << endl;
    }
  }
}

void listItems() {
  for (const auto& [id, item] : inventory) {
    cout << "ID: " << id << ", Description: " << get<string>(item.at("description"))
       << ", Price: " << get<double>(item.at("price"))
       << ", Availability: " << (get<bool>(item.at("availability")) ? "Yes" : "No")
       << ", Quantity: " << get<int>(item.at("quantity"))
       << ", Expiration: " << get<string>(item.at("expiration")) << endl;
  }
}

// Example Usage
int main() {
  addItem("item_1", "Apple", 0.5, true, 100, "2024-10-20");
  addItem("item_2", "Banana", 0.3, true, 5, "2024-10-15");
  listItems();
  checkExpirations();
  checkLowStock();
}

