#define DEFAULT_SIZE 20

void printGrid(int grid[][DEFAULT_SIZE], int size) {
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      printf("%c ", grid[i][j] ? 'O' : '.');
    }
    printf("\n");
  }
}

void updateGrid(int grid[][DEFAULT_SIZE], int size) {
  int newGrid[DEFAULT_SIZE][DEFAULT_SIZE] = {0};
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      int total = 0;
      for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
          if (x == 0 && y == 0) continue;
          int ni = (i + x + size) % size;
          int nj = (j + y + size) % size;
          total += grid[ni][nj];
        }
      }
      if (grid[i][j]) {
        newGrid[i][j] = (total == 2 || total == 3);
      } else {
        newGrid[i][j] = (total == 3);
      }
    }
  }
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      grid[i][j] = newGrid[i][j];
    }
  }
}

void saveGrid(int grid[][DEFAULT_SIZE], int size, const char* filename) {
  FILE* file = fopen(filename, "w");
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      fprintf(file, "%d", grid[i][j]);
    }
    fprintf(file, "\n");
  }
  fclose(file);
}

void loadGrid(int grid[][DEFAULT_SIZE], int size, const char* filename) {
  FILE* file = fopen(filename, "r");
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      fscanf(file, "%1d", &grid[i][j]);
    }
  }
  fclose(file);
}

int main() {
  int size;
  printf("Enter grid size (max %d): ", DEFAULT_SIZE);
  scanf("%d", &size);
  if (size > DEFAULT_SIZE) size = DEFAULT_SIZE;

  int grid[DEFAULT_SIZE][DEFAULT_SIZE] = {0};
  srand(time(NULL));

  // Initialize grid randomly
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      grid[i][j] = rand() % 2;
    }
  }

  int running = 1;
  while (1) {
    if (_kbhit()) {
      _getch(); // Pause/resume on key press
      running = !running;
    }
    if (running) {
      printGrid(grid, size);
      updateGrid(grid, size);
      usleep(200000); // Delay for 0.2 seconds
      printf("\033[H\033[J"); // Clear the console
    }

    // Save the grid state
    if (_kbhit() && _getch() == 's') {
      saveGrid(grid, size, "saved_grid.txt");
      printf("Grid saved to saved_grid.txt\n");
    }

    // Load a predefined pattern or a saved state
    if (_kbhit() && _getch() == 'l') {
      loadGrid(grid, size, "saved_grid.txt");
      printf("Grid loaded from saved_grid.txt\n");
    }
  }

  return 0;
}

