void encoder_fichier(const char *input_file, const char *output_file) {
  FILE *in = fopen(input_file, "rb");
  FILE *out = fopen(output_file, "wb");
  if (in && out) {
    base64_encodestate state;
    base64_init_encodestate(&state);

    char input_buffer[3];
    char output_buffer[4];
    size_t bytes_read;

    while ((bytes_read = fread(input_buffer, 1, sizeof(input_buffer), in)) > 0) {
      base64_encode_block(input_buffer, bytes_read, output_buffer, &state);
      fwrite(output_buffer, 1, 4, out);
    }
    base64_encode_blockend(output_buffer, &state);
    fwrite(output_buffer, 1, 4, out);

    fclose(in);
    fclose(out);
  } else {
    printf("Erreur d'ouverture des fichiers.\n");
  }
}

