class CarInventory {
public:
  std::vector<Car> cars;

  void addCar(const Car& car) {
    cars.push_back(car);
    saveCars();
  }

  void displayCars() {
    for (const auto& car : cars) {
      car.displayInfo();
    }
  }

  void saveCars() {
    std::ofstream outFile("cars.dat", std::ios::binary);
    for (const auto& car : cars) {
      outFile.write(reinterpret_cast<const char*>(&car), sizeof(Car));
    }
  }

  void loadCars() {
    std::ifstream inFile("cars.dat", std::ios::binary);
    if (!inFile) return;
    Car car("", "", 0, "");
    while (inFile.read(reinterpret_cast<char*>(&car), sizeof(Car))) {
      cars.push_back(car);
    }
  }

  Car* searchByLicensePlate(const std::string& licensePlate) {
    for (auto& car : cars) {
      if (car.licensePlate == licensePlate) {
        return &car;
      }
    }
    return nullptr;
  }
};

