int main() {
  const int width = 800;
  const int height = 600;
  sf::RenderWindow window(sf::VideoMode(width, height), "3D Spiral Simulation");

  sf::VertexArray spiral(sf::PrimitiveType::LinesStrip);
  for (float t = 0; t < 10 * M_PI; t += 0.1) {
    float x = 200 * cos(t);
    float y = 200 * sin(t);
    float z = t; // Simulating 3D with color
    sf::Color color = sf::Color(255, 255 - static_cast<int>(z % 255), 255 - static_cast<int>(z % 255));
    spiral.append(sf::Vertex(sf::Vector2f(width / 2 + x, height / 2 + y), color));
  }

  while (window.isOpen()) {
    sf::Event event;
    while (window.pollEvent(event)) {
      if (event.type == sf::Event::Closed)
        window.close();
    }

    window.clear();
    window.draw(spiral);
    window.display();
  }

  return 0;
}

