using namespace std;

class Graph {
  int V;
  vector<vector<int>> capacity;

public:
  Graph(int V) : V(V), capacity(V, vector<int>(V, 0)) {}

  void addEdge(int u, int v, int cap) {
    capacity[u][v] = cap;
  }

  int fordFulkerson(int source, int sink);
};

int bfs(const vector<vector<int>>& residual, vector<int>& parent, int source, int sink) {
  fill(parent.begin(), parent.end(), -1);
  parent[source] = source;
  queue<pair<int, int>> q;
  q.push({source, INT_MAX});

  while (!q.empty()) {
    int u = q.front().first;
    int flow = q.front().second;
    q.pop();

    for (int v = 0; v < residual.size(); ++v) {
      if (parent[v] == -1 && residual[u][v] > 0) {
        parent[v] = u;
        int new_flow = min(flow, residual[u][v]);
        if (v == sink) return new_flow;
        q.push({v, new_flow});
      }
    }
  }
  return 0;
}

int Graph::fordFulkerson(int source, int sink) {
  vector<vector<int>> residual = capacity;
  vector<int> parent(V);
  int max_flow = 0;

  int new_flow;
  while ((new_flow = bfs(residual, parent, source, sink)) > 0) {
    max_flow += new_flow;
    int v = sink;
    while (v != source) {
      int u = parent[v];
      residual[u][v] -= new_flow;
      residual[v][u] += new_flow;
      v = parent[v];
    }
  }
  return max_flow;
}

