class Passenger {
public:
  std::string name;
  std::string passportNumber;
  int age;
  std::string destination;

  Passenger(std::string name, std::string passportNumber, int age, std::string destination)
    : name(name), passportNumber(passportNumber), age(age), destination(destination) {}

  std::string info() const {
    return "Name: " + name + ", Passport: " + passportNumber + ", Age: " + std::to_string(age) + ", Destination: " + destination;
  }
};

class PassengerSystem {
private:
  std::vector<Passenger> passengers;

public:
  void addPassenger(const std::string& name, const std::string& passportNumber, int age, const std::string& destination) {
    if (age < 0) {
      std::cout << "Invalid age." << std::endl;
      return;
    }
    passengers.emplace_back(name, passportNumber, age, destination);
    std::cout << "Passenger " << name << " added successfully." << std::endl;
  }

  Passenger* getPassenger(const std::string& passportNumber) {
    for (auto& passenger : passengers) {
      if (passenger.passportNumber == passportNumber) {
        return &passenger;
      }
    }
    return nullptr;
  }

  void removePassenger(const std::string& passportNumber) {
    auto it = std::remove_if(passengers.begin(), passengers.end(),
      [&passportNumber](const Passenger& p) { return p.passportNumber == passportNumber; });
    if (it != passengers.end()) {
      passengers.erase(it, passengers.end());
      std::cout << "Passenger " << passportNumber << " removed successfully." << std::endl;
    } else {
      std::cout << "Passenger not found." << std::endl;
    }
  }

  void listPassengers() {
    if (passengers.empty()) {
      std::cout << "No passengers found." << std::endl;
    } else {
      for (const auto& passenger : passengers) {
        std::cout << passenger.info() << std::endl;
      }
    }
  }

  void searchByName(const std::string& name) {
    bool found = false;
    for (const auto& passenger : passengers) {
      if (passenger.name == name) {
        std::cout << passenger.info() << std::endl;
        found = true;
      }
    }
    if (!found) {
      std::cout << "No passengers found with the name " << name << std::endl;
    }
  }

  void searchByDestination(const std::string& destination) {
    bool found = false;
    for (const auto& passenger : passengers) {
      if (passenger.destination == destination) {
        std::cout << passenger.info() << std::endl;
        found = true;
      }
    }
    if (!found) {
      std::cout << "No passengers found for destination " << destination << std::endl;
    }
  }

  void sortByName() {
    std::sort(passengers.begin(), passengers.end(),
         [](const Passenger& a, const Passenger& b) { return a.name < b.name; });
    std::cout << "Passengers sorted by name." << std::endl;
  }

  void sortByAge() {
    std::sort(passengers.begin(), passengers.end(),
         [](const Passenger& a, const Passenger& b) { return a.age < b.age; });
    std::cout << "Passengers sorted by age." << std::endl;
  }

  void saveToFile(const std::string& filename) {
    std::ofstream file(filename);
    if (!file) {
      std::cout << "Error opening file for saving." << std::endl;
      return;
    }
    for (const auto& passenger : passengers) {
      file << passenger.name << "," << passenger.passportNumber << "," << passenger.age << "," << passenger.destination << std::endl;
    }
    std::cout << "Passengers saved to " << filename << "." << std::endl;
  }

  void loadFromFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file) {
      std::cout << "Error opening file for loading." << std::endl;
      return;
    }
    std::string line;
    while (std::getline(file, line)) {
      std::string name, passport, destination;
      int age;
      std::stringstream ss(line);
      std::getline(ss, name, ',');
      std::getline(ss, passport, ',');
      ss >> age;
      ss.ignore(); // Ignore the comma
      std::getline(ss, destination);
      addPassenger(name, passport, age, destination);
    }
    std::cout << "Passengers loaded from " << filename << "." << std::endl;
  }
};

