#define DEFAULT_SIZE 20

void printGrid(int grid[][DEFAULT_SIZE], int size) {
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      printf("%c ", grid[i][j] ? 'O' : '.');
    }
    printf("\n");
  }
}

void updateGrid(int grid[][DEFAULT_SIZE], int size) {
  int newGrid[DEFAULT_SIZE][DEFAULT_SIZE] = {0};
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      int total = 0;
      for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
          if (x == 0 && y == 0) continue;
          int ni = (i + x + size) % size;
          int nj = (j + y + size) % size;
          total += grid[ni][nj];
        }
      }
      if (grid[i][j]) {
        newGrid[i][j] = (total == 2 || total == 3);
      } else {
        newGrid[i][j] = (total == 3);
      }
    }
  }
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      grid[i][j] = newGrid[i][j];
    }
  }
}

