  FILE* file = fopen(filename, "w");
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      fprintf(file, "%d", grid[i][j]);
    }
    fprintf(file, "\n");
  }
  fclose(file);
}

