int main() {
  const int width = 800;
  const int height = 600;
  sf::RenderWindow window(sf::VideoMode(width, height), "Spiral Visualization");

  sf::VertexArray spiral(sf::PrimitiveType::LinesStrip);
  for (double t = 0; t < 10 * M_PI; t += 0.1) {
    float x = 100 * t * cos(t);
    float y = 100 * t * sin(t);
    spiral.append(sf::Vertex(sf::Vector2f(width / 2 + x, height / 2 + y), sf::Color::White));
  }

  while (window.isOpen()) {
    sf::Event event;
    while (window.pollEvent(event)) {
      if (event.type == sf::Event::Closed)
        window.close();
    }

    window.clear();
    window.draw(spiral);
    window.display();
  }

  return 0;
}

