    return dydt;
  };

  VectorXd y0(1);
  y0[0] = 0.5;

  double t0 = 0.0;
  double t1 = 5.0;
  int steps = 1000;
  double dt = (t1 - t0) / steps;

  VectorXd y = y0;
  double t = t0;

  for (int i = 0; i < steps; ++i) {
    y += dt * model(y, t);
    t += dt;
  }

