#include <iostream>
#include <string>
#include <sqlite3.h>

class Car {
public:
  std::string make;
  std::string model;
  int year;
  std::string licensePlate;
  std::string nextMaintenance; // Format: YYYY-MM-DD

  Car(std::string make, std::string model, int year, std::string licensePlate, std::string nextMaintenance)
    : make(make), model(model), year(year), licensePlate(licensePlate), nextMaintenance(nextMaintenance) {}
};

class CarInventory {
public:
  void createTables(sqlite3* db) {
    const char* carSql = "CREATE TABLE IF NOT EXISTS cars (make TEXT, model TEXT, year INTEGER, license_plate TEXT PRIMARY KEY, next_maintenance DATE);";
    const char* locationSql = "CREATE TABLE IF NOT EXISTS locations (license_plate TEXT, location TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(license_plate) REFERENCES cars(license_plate));";
    const char* geofenceSql = "CREATE TABLE IF NOT EXISTS geofences (license_plate TEXT, latitude REAL, longitude REAL, radius REAL, FOREIGN KEY(license_plate) REFERENCES cars(license_plate));";
    char* errMsg;
    sqlite3_exec(db, carSql, 0, 0, &errMsg);
    sqlite3_exec(db, locationSql, 0, 0, &errMsg);
    sqlite3_exec(db, geofenceSql, 0, 0, &errMsg);
    if (errMsg) {
      std::cerr << "SQL error: " << errMsg << std::endl;
      sqlite3_free(errMsg);
    }
  }

  void addCar(sqlite3* db, const Car& car) {
    sqlite3_stmt* stmt;
    const char* sql = "INSERT INTO cars (make, model, year, license_plate, next_maintenance) VALUES (?, ?, ?, ?, ?);";
    sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
    sqlite3_bind_text(stmt, 1, car.make.c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, car.model.c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_int(stmt, 3, car.year);
    sqlite3_bind_text(stmt, 4, car.licensePlate.c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 5, car.nextMaintenance.c_str(), -1, SQLITE_STATIC);
    sqlite3_step(stmt);
    sqlite3_finalize(stmt);
  }

  void addGeofence(sqlite3* db, const std::string& licensePlate, double latitude, double longitude, double radius) {
    sqlite3_stmt* stmt;
    const char* sql = "INSERT INTO geofences (license_plate, latitude, longitude, radius) VALUES (?, ?, ?, ?);";
    sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
    sqlite3_bind_text(stmt, 1, licensePlate.c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_double(stmt, 2, latitude);
    sqlite3_bind_double(stmt, 3, longitude);
    sqlite3_bind_double(stmt, 4, radius);
    sqlite3_step(stmt);
    sqlite3_finalize(stmt);
  }

  void displayMaintenance(sqlite3* db) {
    sqlite3_stmt* stmt;
    const char* sql = "SELECT license_plate, next_maintenance FROM cars;";
    sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
    while (sqlite3_step(stmt) == SQLITE_ROW) {
      std::cout << "License Plate: " << reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0))
           << " | Next Maintenance: " << reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1)) << std::endl;
    }
    sqlite3_finalize(stmt);
  }
};

