using namespace CryptoPP;

int main() {
  // Generate a random key and IV
  byte key[AES::DEFAULT_KEYLENGTH];
  byte iv[AES::BLOCKSIZE];
  AutoSeededRandomPool rng;
  rng.GenerateBlock(key, sizeof(key));
  rng.GenerateBlock(iv, sizeof(iv));

  std::string plaintext = "Hello, world!";
  std::string ciphertext;

  // Encrypt the plaintext
  try {
    CBC_Mode_ExternalCipher::Encryption enc;
    enc.SetKeyWithIV(key, sizeof(key), iv);

    StringSource ss(plaintext, true, new StreamTransformationFilter(enc, new StringSink(ciphertext)));
  } catch (const Exception& e) {
    std::cerr << e.what() << std::endl;
  }

  std::string encoded_ciphertext;
  StringSource(ciphertext, true, new HexEncoder(new StringSink(encoded_ciphertext)));

  std::cout << "Ciphertext: " << encoded_ciphertext << std::endl;

  // Decrypt the ciphertext
  std::string decryptedtext;
  try {
    CBC_Mode_ExternalCipher::Decryption dec;
    dec.SetKeyWithIV(key, sizeof(key), iv);

    StringSource ss(ciphertext, true, new StreamTransformationFilter(dec, new StringSink(decryptedtext)));
  } catch (const Exception& e) {
    std::cerr << e.what() << std::endl;
  }

  std::cout << "Decrypted message: " << decryptedtext << std::endl;

  return 0;
}

