std::string hash_password(const std::string &password) {
  SecByteBlock salt(16);
  AutoSeededRandomPool prng;
  prng.GenerateBlock(salt, salt.size());

  std::string hashed;
  PKCS5_PBKDF2_HMAC<SHA256> pbkdf2;
  hashed.resize(32);
  pbkdf2.DeriveKey((byte*)hashed.data(), hashed.size(),
           0, (const byte*)password.data(), password.size(),
           salt.data(), salt.size(), 10000);

  return hashed + std::string((const char*)salt.data(), salt.size());
}

