struct Car {
  char make[50];
  char model[50];
  int year;
  char licensePlate[20];
  char nextMaintenance[11]; // Format: YYYY-MM-DD
};

void create_tables(sqlite3 *db) {
  const char *car_sql = "CREATE TABLE IF NOT EXISTS cars (make TEXT, model TEXT, year INTEGER, license_plate TEXT PRIMARY KEY, next_maintenance DATE);";
  const char *location_sql = "CREATE TABLE IF NOT EXISTS locations (license_plate TEXT, location TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(license_plate) REFERENCES cars(license_plate));";
  const char *geofence_sql = "CREATE TABLE IF NOT EXISTS geofences (license_plate TEXT, latitude REAL, longitude REAL, radius REAL, FOREIGN KEY(license_plate) REFERENCES cars(license_plate));";
  char *err_msg = 0;

  sqlite3_exec(db, car_sql, 0, 0, &err_msg);
  sqlite3_exec(db, location_sql, 0, 0, &err_msg);
  sqlite3_exec(db, geofence_sql, 0, 0, &err_msg);
  if (err_msg != 0) {
    fprintf(stderr, "SQL error: %s\n", err_msg);
    sqlite3_free(err_msg);
  }
}

void register_car(sqlite3 *db, struct Car car) {
  sqlite3_stmt *stmt;
  const char *sql = "INSERT INTO cars (make, model, year, license_plate, next_maintenance) VALUES (?, ?, ?, ?, ?);";
  sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
  sqlite3_bind_text(stmt, 1, car.make, -1, SQLITE_STATIC);
  sqlite3_bind_text(stmt, 2, car.model, -1, SQLITE_STATIC);
  sqlite3_bind_int(stmt, 3, car.year);
  sqlite3_bind_text(stmt, 4, car.licensePlate, -1, SQLITE_STATIC);
  sqlite3_bind_text(stmt, 5, car.nextMaintenance, -1, SQLITE_STATIC);
  sqlite3_step(stmt);
  sqlite3_finalize(stmt);
}

void add_geofence(sqlite3 *db, const char *licensePlate, double latitude, double longitude, double radius) {
  sqlite3_stmt *stmt;
  const char *sql = "INSERT INTO geofences (license_plate, latitude, longitude, radius) VALUES (?, ?, ?, ?);";
  sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
  sqlite3_bind_text(stmt, 1, licensePlate, -1, SQLITE_STATIC);
  sqlite3_bind_double(stmt, 2, latitude);
  sqlite3_bind_double(stmt, 3, longitude);
  sqlite3_bind_double(stmt, 4, radius);
  sqlite3_step(stmt);
  sqlite3_finalize(stmt);
}

