  std::string category;
  std::set<Employee*> attendees;
  std::vector<std::string> reminders; // New field for reminders

  Event(std::string t, std::string d, std::string desc, bool recurring = false, std::string cat = "") 
    : title(t), date(d), description(desc), isRecurring(recurring), category(cat) {}

  void display() {
    std::cout << "Event: " << title << ", Date: " << date 
         << ", Description: " << description 
         << ", Recurring: " << (isRecurring ? "Yes" : "No") 
         << ", Category: " << category << std::endl;
    if (!reminders.empty()) {
      std::cout << "Reminders: ";
      for (const auto& reminder : reminders) {
        std::cout << reminder << " ";
      }
      std::cout << std::endl;
    }
  }

  void addAttendee(Employee* emp) {
    attendees.insert(emp);
  }

  void addReminder(const std::string& reminder) {
    reminders.push_back(reminder);
  }
};

class Employee {
public:
  std::string name;
  std::string position;
  double salary;
  double performanceRating;
  std::vector<Event> events;
  bool isManager; // New field to identify role

  Employee(std::string n, std::string p, double s, bool isMgr) 
    : name(n), position(p), salary(s), performanceRating(0), isManager(isMgr) {}

  void display() {
    std::cout << position << ": " << name << ", Salary: " << salary 
         << ", Performance Rating: " << performanceRating << std::endl;
    std::cout << "Events:" << std::endl;
    for (const auto& event : events) {
      event.display();
    }
  }

  void addEvent(const Event& event) {
    for (const auto& e : events) {
      if (e.date == event.date && e.attendees.find(this) != e.attendees.end()) {
        std::cout << "Conflict detected: " << e.title << std::endl;
        return;
      }
    }
    events.push_back(event);
    events.back().addAttendee(this);
  }

  void notifyUpcomingEvents(const std::string& currentDate) {
    for (const auto& event : events) {
      if (event.date == currentDate) {
        std::cout << "Notification: " << name << ", you have an upcoming event: " << event.title << std::endl;
      }
    }
  }
};

class Department {
public:
  std::string name;
  std::vector<Employee> employees;

  Department(std::string n) : name(n) {}

  void addEmployee(const Employee& emp) {
    employees.push_back(emp);
  }

  void displayEmployees() {
    std::cout << "Department: " << name << std::endl;
    for (const auto& emp : employees) {
      emp.display();
    }
  }

  void searchEvents(const std::string& keyword) {
    std::cout << "Search Results:" << std::endl;
    for (const auto& emp : employees) {
      for (const auto& event : emp.events) {
        if (event.title.find(keyword) != std::string::npos || event.category.find(keyword) != std::string::npos) {
          event.display();
        }
      }
    }
  }
};

