#include <gtk/gtk.h>

static void add_task(GtkWidget *widget, gpointer data) {
  GtkListStore *store = GTK_LIST_STORE(data);
  GtkEntry *entry = GTK_ENTRY(g_object_get_data(G_OBJECT(widget), "entry"));
  const gchar *task = gtk_entry_get_text(entry);

  if (task && *task) {
    GtkTreeIter iter;
    gtk_list_store_append(store, &iter);
    gtk_list_store_set(store, &iter, 0, task, -1);
    gtk_entry_set_text(entry, "");
  }
}

static void remove_task(GtkWidget *widget, gpointer data) {
  GtkTreeSelection *selection = GTK_TREE_SELECTION(data);
  GtkTreeModel *model;
  GtkTreeIter iter;

  if (gtk_tree_selection_get_selected(selection, &model, &iter)) {
    gtk_list_store_remove(GTK_LIST_STORE(model), &iter);
  }
}

