  FILE* file = fopen(filename, "w");
  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      fputc(grid[i][j] ? '1' : '0', file);
    }
    fputc('\n', file);
  }
  fclose(file);
  printf("Pattern exported to %s\n", filename);
