  int susceptible = population - initial_infected;
  int infected = initial_infected;
  int recovered = 0;

  srand(static_cast<unsigned>(time(0)));

  for (int day = 0; day < days; day++) {
    int new_infected = 0;
    for (int i = 0; i < infected; i++) {
      if (susceptible > 0 && (static_cast<double>(rand()) / RAND_MAX) < beta) {
        new_infected++;
      }
    }
    new_infected = std::min(new_infected, susceptible);
    int new_recovered = static_cast<int>(gamma * infected);

