class Node {
public:
  int data;
  Node* next;
  Node(int data) : data(data), next(nullptr) {}
};

class LinkedList {
private:
  Node* head;

public:
  LinkedList() : head(nullptr) {}

  void append(int data) {
    Node* new_node = new Node(data);
    if (!head) {
      head = new_node;
    } else {
      Node* current = head;
      while (current->next) {
        current = current->next;
      }
      current->next = new_node;
    }
  }

  Node* merge(Node* list1, Node* list2) {
    Node dummy(0);
    Node* tail = &dummy;
    while (list1 && list2) {
      if (list1->data < list2->data) {
        tail->next = list1;
        list1 = list1->next;
      } else {
        tail->next = list2;
        list2 = list2->next;
      }
      tail = tail->next;
    }
    tail->next = list1 ? list1 : list2;
    return dummy.next;
  }

  void display(Node* node) {
    while (node) {
      std::cout << node->data << " -> ";
      node = node->next;
    }
    std::cout << "NULL" << std::endl;
  }
};

