int main() {
  const int width = 800;
  const int height = 800;
  sf::RenderWindow window(sf::VideoMode(width, height), "Spirograph");

  int R = 100; // Fixed radius
  int r = 50; // Radius of moving circle
  int d = 25; // Distance from the center of the moving circle to the drawing point
  sf::VertexArray spirograph(sf::PrimitiveType::LinesStrip);

  for (double theta = 0; theta < 10 * M_PI; theta += 0.01) {
    double x = (R - r) * cos(theta) + d * cos((R - r) / r * theta);
    double y = (R - r) * sin(theta) - d * sin((R - r) / r * theta);
    spirograph.append(sf::Vertex(sf::Vector2f(width / 2 + x, height / 2 + y), sf::Color::White));
  }

  while (window.isOpen()) {
    sf::Event event;
    while (window.pollEvent(event)) {
      if (event.type == sf::Event::Closed)
        window.close();
    }

    window.clear();
    window.draw(spirograph);
    window.display();
  }

  return 0;
}

