  auto fromZone = locate_zone(fromTz);
  auto toZone = locate_zone(toTz);

  auto localTime = fromZone->to_local(datetime);
  auto targetTime = toZone->to_sys(localTime);

  std::cout << "Converted date: " << format("%F %T", targetTime) << std::endl;
}

