class Employee {
public:
  std::string name;
  std::string position;
  double salary;
  double performanceRating; // Default rating

  Employee(std::string n, std::string p, double s) : name(n), position(p), salary(s), performanceRating(0) {}

  void display() {
    std::cout << position << ": " << name << ", Salary: " << salary << ", Performance Rating: " << performanceRating << std::endl;
  }

  double calculateBonus() {
    return salary * 0.1; // 10% bonus
  }

  void promote() {
    if (performanceRating >= 4.5) {
      if (position == "Intern") {
        position = "Developer";
        salary += 20000; // Example promotion raise
      } else if (position == "Developer") {
        position = "Manager";
        salary += 30000; // Example promotion raise
      }
    }
  }
};

class Department {
public:
  std::string name;
  std::vector<Employee> employees;

  Department(std::string n) : name(n) {}

  void addEmployee(const Employee& emp) {
    employees.push_back(emp);
  }

  void displayEmployees() {
    std::cout << "Department: " << name << std::endl;
    for (const auto& emp : employees) {
      emp.display();
    }
  }

  Employee* searchEmployee(const std::string& name) {
    for (auto& emp : employees) {
      if (emp.name == name) {
        return &emp;
      }
    }
    return nullptr;
  }

  void saveToFile(const std::string& filename) {
    std::ofstream ofs(filename, std::ios::binary);
    for (const auto& emp : employees) {
      ofs.write(reinterpret_cast<const char*>(&emp), sizeof(Employee));
    }
  }

  void loadFromFile(const std::string& filename) {
    std::ifstream ifs(filename, std::ios::binary);
    Employee emp("", "", 0);
    while (ifs.read(reinterpret_cast<char*>(&emp), sizeof(Employee))) {
      employees.push_back(emp);
    }
  }
};

int main() {
  Department dev_department("Development");
  Employee emp1("Alice", "Manager", 80000);
  Employee emp2("Bob", "Developer", 60000);
  Employee emp3("Charlie", "Intern", 30000);

  emp1.performanceRating = 4.6;
  emp2.performanceRating = 4.2;
  emp3.performanceRating = 4.8;

  dev_department.addEmployee(emp1);
  dev_department.addEmployee(emp2);
  dev_department.addEmployee(emp3);

  dev_department.displayEmployees();

  // Promote employees based on performance
  for (auto& emp : dev_department.employees) {
    emp.promote();
  }

  std::cout << "After Promotion:\n";
  dev_department.displayEmployees();

  // Save employees to a file
  dev_department.saveToFile("employees.dat");
  std::cout << "Employees saved to file." << std::endl;

  return 0;
}

